class Solution {
public:
    int balancedString(string s) {
        int n = s.size();
        int k = n / 4;
        auto idx = [](char c) -> int {
            switch (c) {
                case 'Q': return 0;
                case 'W': return 1;
                case 'E': return 2;
                default:  return 3;
            }
        };
        int cnt[4] = {0, 0, 0, 0};
        for (char c : s) cnt[idx(c)]++;
        bool balanced = true;
        for (int i = 0; i < 4; i++) {
            if (cnt[i] > k) { balanced = false; break; }
        }
        if (balanced) return 0;
        int ans = n;
        int window[4] = {0, 0, 0, 0};
        int left = 0;
        for (int right = 0; right < n; right++) {
            window[idx(s[right])]++;
            while (left <= right) {
                bool ok = true;
                for (int i = 0; i < 4; i++) {
                    if (cnt[i] - window[i] > k) { ok = false; break; }
                }
                if (!ok) break;
                int len = right - left + 1;
                if (len < ans) ans = len;
                window[idx(s[left])]--;
                left++;
            }
        }
        return ans;
    }
};
